import{_ as t,o as i,c as s,a4 as a}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse(`{"title":"ADR-0057 — Authenticité des images vérifiée à l'installation","description":"Extrait de docs/adr/0057-authenticite-des-images-a-l-installation.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0057 — Authenticité des images vérifiée à l'installation","description":"Extrait de docs/adr/0057-authenticite-des-images-a-l-installation.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0057-authenticite-des-images-a-l-installation.md","filePath":"developpeurs/adr/0057-authenticite-des-images-a-l-installation.md"}`),n={name:"developpeurs/adr/0057-authenticite-des-images-a-l-installation.md"};function r(o,e,l,c,d,u){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0057--authenticité-des-images-vérifiée-à-linstallation" tabindex="-1">ADR-0057 — Authenticité des images vérifiée à l&#39;installation <a class="header-anchor" href="#adr-0057--authenticité-des-images-vérifiée-à-linstallation" aria-label="Permalink to &quot;ADR-0057 — Authenticité des images vérifiée à l&#39;installation {#adr-0057--authenticité-des-images-vérifiée-à-linstallation}&quot;">​</a></h1><p><strong>Date :</strong> 28 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit complet du 26 septembre 2026, constat EXP-10 (moyen) <strong>Amende :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0045-deploiement-par-un-exploitant-non-developpeur">ADR-0045</a>, décisions n°1 (images signées par cosign) et n°3 (installateur) <strong>Amendée par :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0062-signature-par-cosign-v3">ADR-0062</a> (signature en cosign v3 ; un cosign antérieur est traité comme absent) <strong>Complétée par :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0063-depot-public-de-distribution">ADR-0063</a> (l&#39;archive de la pile se télécharge depuis un dépôt public de distribution ; l&#39;identité de signature reste le dépôt du code)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>L&#39;ADR-0045 fait signer les images <code>teuthis-api</code> et <code>teuthis-admin</code> par cosign, sans clé, avec l&#39;identité du workflow <code>publication-images.yml</code>. Personne ne vérifiait cette signature : l&#39;installateur téléchargeait les images par étiquette (<code>X.Y.Z</code>), et seule l&#39;archive de la pile était contrôlée par sa somme SHA-256.</p><p>L&#39;audit relève (EXP-10) que cette somme garantit l&#39;<strong>intégrité</strong> de l&#39;archive, pas l&#39;<strong>authenticité</strong> des images. Elle est publiée à côté de l&#39;archive, sur la même release. Une étiquette republiée sur une autre image, ou un compte capable d&#39;écrire dans le registre, passaient inaperçus.</p><p>cosign n&#39;est pas installé sur un serveur Debian ou Ubuntu de base, et n&#39;est pas dans leurs dépôts stables. L&#39;exiger ajouterait une dépendance à télécharger hors des dépôts du système, ce que l&#39;installateur évite (ADR-0045, décision n°3 : « aucun tiers contacté » hors Docker, GitHub, le registre et Let&#39;s Encrypt).</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><ol><li><p><strong>Les empreintes des images publiées sont figées dans l&#39;archive de la pile.</strong> Le job <code>archive-deploiement</code> de <code>publication-images.yml</code> s&#39;exécute désormais <strong>après</strong> le job <code>publication</code>. Il écrit <code>images-publiees.txt</code> dans <code>teuthis-deploy-X.Y.Z.tar.gz</code>, avec une ligne par image poussée : <code>ghcr.io/bastien-oc20/teuthis-&lt;nom&gt;:X.Y.Z@sha256:&lt;empreinte de l&#39;index multi-architecture&gt;</code>. La somme SHA-256 de l&#39;archive, que l&#39;installateur vérifie déjà, couvre donc aussi ces empreintes. Une répétition à blanc ne pousse rien, et son archive n&#39;a pas ce fichier.</p></li><li><p><strong>L&#39;installateur refuse toute image tirée qui n&#39;a pas l&#39;empreinte publiée</strong>, que cosign soit présent ou non. Après <code>docker compose pull</code>, l&#39;étiquette locale doit désigner exactement l&#39;empreinte de <code>images-publiees.txt</code>. Il refuse aussi un fichier illisible, ou un fichier d&#39;une autre version que celle installée.</p></li><li><p><strong>Si <code>cosign</code> est présent sur le serveur</strong>, l&#39;installateur vérifie avant le téléchargement la signature de chaque image, désignée par son empreinte :</p><ul><li><code>--certificate-identity-regexp</code> : <code>^https://github\\.com/&lt;dépôt&gt;/\\.github/workflows/publication-images\\.yml@refs/tags/vX\\.Y\\.Z$</code>, c&#39;est-à-dire ce dépôt, ce workflow et l&#39;étiquette de la version installée ;</li><li><code>--certificate-oidc-issuer</code> : <code>https://token.actions.githubusercontent.com</code>.</li></ul><p>Un échec <strong>arrête l&#39;installation</strong> avant tout démarrage, avec un message qui dit quoi faire, et ne propose jamais de contourner le refus.</p></li><li><p><strong>Si <code>cosign</code> est absent</strong>, l&#39;installateur l&#39;annonce clairement et continue. L&#39;avertissement dit ce qui reste vérifié (l&#39;empreinte, point n°2), ce qui ne l&#39;est pas (que l&#39;image vient du workflow de publication de ce dépôt), et comment installer cosign. <strong>L&#39;installateur n&#39;installe pas cosign lui-même.</strong></p></li><li><p><strong>Les images locales ne sont pas concernées</strong> : une image fournie par <code>TEUTHIS_IMAGE_API</code> ou <code>TEUTHIS_IMAGE_ADMIN</code> n&#39;est ni tirée ni vérifiée au registre. Une pile recopiée par <code>--source</code> (essais) n&#39;a pas d&#39;empreintes, et le dit sans avertissement.</p></li><li><p><strong>Testé par bats</strong> (<code>deploy/tests/installer.bats</code>), avec cosign simulé par un faux binaire dans le <code>PATH</code> : cosign absent, cosign qui accepte, cosign qui refuse. S&#39;y ajoutent l&#39;image locale, la version discordante, la ligne illisible, la pile <code>--source</code>, l&#39;empreinte tirée conforme ou non, et la copie du fichier d&#39;empreintes.</p></li></ol><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Exiger cosign, l&#39;installer s&#39;il manque</strong></td><td>Il faut le télécharger depuis GitHub hors des dépôts du système, avec sa propre somme à vérifier : on déplace le problème. Cela ajoute aussi une dépendance que l&#39;exploitant ne maintiendra pas. Le Product Owner a choisi l&#39;avertissement.</td></tr><tr><td><strong>Empreintes gravées dans <code>compose.yml</code></strong> (<code>image: …@sha256:</code>)</td><td>Il faudrait réécrire <code>compose.yml</code> à la publication, et <code>TEUTHIS_IMAGE_API</code>, qui remplace la référence entière, en deviendrait plus fragile. <code>compose.yml</code> resterait aussi différent entre le dépôt et l&#39;archive. Un fichier à part garde <code>compose.yml</code> identique partout.</td></tr><tr><td><strong>Empreintes dans les notes de la release seulement</strong></td><td>Elles sont lisibles par un humain, mais l&#39;installateur ne les lit pas, et elles sont modifiables après coup sans changer la somme de l&#39;archive.</td></tr><tr><td><strong>Vérifier par <code>docker trust</code> / Notary</strong></td><td>GHCR ne le prend pas en charge, et les images sont déjà signées par cosign (ADR-0045).</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Une étiquette republiée sur une autre image est refusée sur tout serveur, avec ou sans cosign.</li><li>Avec cosign, une image qui ne vient pas du workflow de publication de ce dépôt, sur l&#39;étiquette de cette version, est refusée avant tout démarrage.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Sans cosign, l&#39;authenticité repose sur la release GitHub.</strong> Un attaquant qui peut à la fois pousser dans le registre et remplacer l&#39;archive et sa somme sur la release n&#39;est pas détecté. L&#39;avertissement le dit.</li><li>L&#39;archive de la pile est désormais préparée après la publication des images, donc un peu plus tard dans le workflow.</li><li>Avec cosign, l&#39;installation contacte en plus l&#39;infrastructure publique de Sigstore (Rekor, Fulcio, TUF). Sa panne arrête l&#39;installation, et c&#39;est voulu : on ne démarre jamais une image non vérifiée quand la vérification a été demandée.</li><li>Les versions publiées avant cette ADR n&#39;ont pas <code>images-publiees.txt</code>. L&#39;installateur les installe avec un avertissement.</li><li>Les images tierces de la pile (Caddy, PostgreSQL, ClamAV, Tika, Ollama) restent épinglées par digest dans <code>compose.yml</code> (ADR-0045 ; EXP-8). Leur signature n&#39;est pas vérifiée.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Empreintes figées dans l&#39;archive, vérification à l&#39;installation, tests — <code>.github/workflows/publication-images.yml</code> (job <code>archive-deploiement</code> après <code>publication</code>, <code>images-publiees.txt</code>), <code>deploy/installer.sh</code> (<code>verifier_authenticite_images</code>, <code>verifier_empreintes_tirees</code>, <code>references_a_verifier</code>), <code>deploy/tests/installer.bats</code> (10 tests, 104 au total), <code>deploy/LISEZMOI.md</code>.</li><li>[x] Première release publiée avec <code>images-publiees.txt</code>, et installation réelle avec cosign présent : la vérification contre Sigstore et GHCR ne peut s&#39;éprouver que sur une vraie publication. <strong>Fait le 30/09/2026</strong> — release v0.2.1 (<code>calamars</code> et <code>teuthis-cms-distribution</code>), images <code>teuthis-api@sha256:78ce6fcb…</code> et <code>teuthis-admin@sha256:fdbccfe2…</code> publiques ; installation réelle sur un Ubuntu 24.04 jetable, sans compte GitHub, avec cosign v3.1.3 : installateur et archive vérifiés par leur somme, « Signature vérifiée » et « Empreinte conforme » pour les deux images, six services sains, <code>/api/sante</code> en HTTPS (200). <code>cosign verify</code> refuse la même image contre l&#39;étiquette <code>v9.9.9</code> (contre-épreuve).</li></ul>',17)])])}const m=t(n,[["render",r]]);export{g as __pageData,m as default};
